describe('Search Filter by Category', () => {
    beforeEach(() => {
        cy.visit('/search');
    });

    it('should filter search results by selected category', () => {
        cy.get('input[type="checkbox"][value="electronics"]').check();
        cy.get('input[type="checkbox"][value="books"]').check();
        cy.get('button[type="submit"]').click();

        cy.get('.search-results').should('exist');
        cy.get('.search-results .item').each(($item) => {
            cy.wrap($item).find('.category').should('match', /electronics|books/);
        });
    });

    it('should show all results when no category is selected', () => {
        cy.get('button[type="submit"]').click();

        cy.get('.search-results').should('exist');
        cy.get('.search-results .item').should('have.length.greaterThan', 0);
    });
});
